#include <vector>
#include <iostream>
#include <algorithm>

int get_span(const std::vector<int>& arr, int start_idx, int max_diff) {
    int count = 1;
    for (int j = start_idx + 1; j < (int)arr.size(); ++j) {
        if (arr[j] - arr[start_idx] > max_diff)
            break;
        ++count;
    }
    return count;
}

int main() {
    std::vector<int> data;
    int n, t;
    std::cin >> n;
    for (int i = 0; i < n; ++i) {
        int val;
        std::cin >> val;
        data.push_back(val);
    }
    std::cin >> t;
    std::sort(data.begin(), data.end());
    int max_count = 0;
    for (int i = 0; i < (int)data.size(); ++i) {
        int span_len = get_span(data, i, t);
        if (span_len > max_count)
            max_count = span_len;
    }
    std::cout << max_count << "\n";
}
